/**
 * Live probe for the Photon iMessage integration. Reads credentials from the
 * environment; nothing is written to disk.
 */
import { Spectrum } from '@spectrum-ts/core'
import { imessage } from '@spectrum-ts/imessage'

const projectId = process.env.SPECTRUM_PROJECT_ID
const projectSecret = process.env.SPECTRUM_PROJECT_SECRET

if (!(projectId && projectSecret)) {
  throw new Error('Missing SPECTRUM_PROJECT_ID / SPECTRUM_PROJECT_SECRET')
}

console.log('constructing Spectrum instance...')
const started = Date.now()
const app = await Spectrum({
  projectId,
  projectSecret,
  providers: [imessage.config()],
})
console.log(`instance ready in ${Date.now() - started}ms`)

console.log('project config:', JSON.stringify(app.config, null, 2))

const platform = imessage(app)
console.log('narrowed platform ok:', typeof platform.space?.create === 'function')

const target = process.env.PROBE_TO
if (target) {
  console.log(`resolving DM for ${target}...`)
  const user = await platform.user(target)
  const space = await platform.space.create(user)
  console.log('space:', JSON.stringify(space, null, 2))

  const text = process.env.PROBE_TEXT ?? 'Photon → Sim integration probe'
  const sent = await space.send(text)
  console.log('sent:', JSON.stringify({ id: sent?.id, timestamp: sent?.timestamp }, null, 2))
} else {
  console.log('PROBE_TO not set — skipping send')
}

await app.stop()
console.log('stopped cleanly')

