/**
 * Live round-trip: wait for one real inbound iMessage, dump its normalized shape
 * (ground truth for the trigger's formatInput mapping), then reply through the
 * exact code path the Sim send tool uses for the chatId branch.
 */
import { Spectrum, text } from '@spectrum-ts/core'
import { imessage } from '@spectrum-ts/imessage'

const TIMEOUT_MS = 300_000

const app = await Spectrum({
  projectId: process.env.SPECTRUM_PROJECT_ID as string,
  projectSecret: process.env.SPECTRUM_PROJECT_SECRET as string,
  providers: [imessage.config()],
})

const platform = imessage(app)
console.log('LISTENING — text the Photon number now. Waiting up to 5 minutes...')

const timer = setTimeout(() => {
  console.log('TIMEOUT — no inbound message received')
  app.stop().then(() => process.exit(1))
}, TIMEOUT_MS)

for await (const [space, message] of app.messages) {
  clearTimeout(timer)

  console.log('=== INBOUND (normalized model the webhook serializes) ===')
  console.log(
    JSON.stringify(
      {
        id: message.id,
        platform: message.platform,
        direction: message.direction,
        timestamp: message.timestamp,
        sender: message.sender,
        space: { id: space.id, ...space },
        content: message.content,
      },
      (_k, v) => (typeof v === 'function' ? '[fn]' : v),
      2
    )
  )

  // The Sim send tool's chatId branch: resolve the chat by GUID, then send text.
  const target = await platform.space.get(space.id)
  const sent = await target.send(text('Photon → Sim integration verified ✅'))
  console.log('=== OUTBOUND RESULT ===')
  console.log(JSON.stringify({ id: sent?.id, timestamp: sent?.timestamp }, null, 2))

  break
}

await app.stop()
console.log('DONE')
process.exit(0)

